// ── EDIT THIS NODE TO UPDATE YOUR PROFILE EVERYWHERE ──
const profile = {
  name: 'Yahya Ahmed',
  location: 'Nairobi, Kenya',
  summary: 'AI Engineer and Machine Learning Specialist with 9+ years in enterprise automation, data analytics, and geostrategic economic research. Expert at turning complex data into production-grade automated solutions.',
  skills: ['n8n', 'Python', 'NumPy', 'SymPy', 'SQL', 'Google Cloud Platform', 'Vertex AI', 'Machine Learning', 'Data Science', 'AI Orchestration', 'Multi-agent Systems', 'LLMs', 'Data Visualization', 'K-Means Clustering', 'Predictive Modeling', 'EDA'],
  experience: [
    { title: 'Founder & Principal Consultant', company: 'YSL Solutions', period: 'Jan 2026 – Present' },
    { title: 'Agribusiness Entrepreneur', company: 'Seed Distribution Venture (Nairobi)', period: '2026 – Present' },
    { title: 'Economic Researcher', company: 'United Nations Economic Commission for Africa', period: 'Past' }
  ],
  education: [
    { degree: 'Master of Data Science (Candidate)', school: 'University of Pittsburgh', notes: 'Focus: LLMs & Data Visualization | 98% performance metric' },
    { degree: 'B.S. Agricultural Biotechnology & Agroecology', school: 'Virginia Tech' }
  ],
  certifications: ['Google Cloud Professional Data Engineer (GCP)', 'IABAC Certified Data Scientist & AI Expert']
};

const searches = [
  { keywords: 'AI engineer workflow automation n8n',      location: 'Remote' },
  { keywords: 'data scientist machine learning GCP',       location: 'Remote' },
  { keywords: 'AI consultant automation specialist',       location: '' }
];

return searches.map(s => ({ json: { profile, ...s } }));

const html = $input.item.json.data || '';
const profile = $input.item.json.profile;
const searchKeywords = $input.item.json.keywords;
const results = [];

const liBlocks = html.split(/<\/li>/);

for (const block of liBlocks) {
  if (!block.includes('base-card')) continue;

  const titleMatch   = block.match(/class="[^"]*base-search-card__title[^"]*"[^>]*>[\s]*([^<]+)[\s]*<\/h3>/);
  const title        = titleMatch ? titleMatch[1].trim() : null;
  if (!title) continue;

  const companyMatch  = block.match(/class="[^"]*base-search-card__subtitle[^"]*"[^>]*>[\s]*(?:<[^>]+>[\s]*)*([^<]+)[\s]*<\//);
  const company       = companyMatch ? companyMatch[1].trim() : 'Unknown';

  const locMatch      = block.match(/class="[^"]*job-search-card__location[^"]*"[^>]*>[\s]*([^<]+)[\s]*<\/span>/);
  const jobLocation   = locMatch ? locMatch[1].trim() : 'Unknown';

  const dateMatch     = block.match(/datetime="([^"]+)"/);
  const postedDate    = dateMatch ? dateMatch[1] : '';

  const urlMatch      = block.match(/href="(https:\/\/[^"]*linkedin\.com\/jobs\/view\/[^"?]+)/);
  const jobUrl        = urlMatch ? urlMatch[1].split('?')[0] : '';

  const idMatch       = jobUrl.match(/view\/(\d+)/);
  const jobId         = idMatch ? idMatch[1] : (company + '-' + title).toLowerCase().replace(/\s+/g, '-').replace(/[^a-z0-9-]/g, '');

  const haystack      = (title + ' ' + company).toLowerCase();
  const matched       = profile.skills.filter(s => haystack.includes(s.toLowerCase()));
  const score         = matched.length;

  results.push({
    json: {
      job_id: jobId, title, company,
      location: jobLocation, posted_date: postedDate, job_url: jobUrl,
      search_query: searchKeywords, matched_skills: matched.join(', '),
      relevance_score: score,
      date_found: new Date().toISOString().split('T')[0],
      source: 'LinkedIn', profile
    }
  });
}

if (results.length === 0) {
  return [{ json: {
    job_id: null, title: 'No jobs found', company: null, location: null,
    posted_date: null, job_url: null, search_query: searchKeywords,
    matched_skills: '', relevance_score: 0,
    date_found: new Date().toISOString().split('T')[0],
    source: 'LinkedIn', profile
  }}];
}

return results;

const job = $input.item.json;

const systemPrompt = 'You are an expert resume writer and career coach specializing in AI, Data Science, and Technology roles. Tailor a candidate resume for the given job. Return ONLY a raw JSON object (no markdown, no code fences) with these four fields: tailored_summary (2-3 sentences), key_skills (array of 6-8 strings), cover_note (one concise paragraph), match_assessment (one sentence rating the fit).';

const userPrompt = [
  'JOB DETAILS:',
  'Title: ' + job.title,
  'Company: ' + job.company,
  'Location: ' + job.location,
  'URL: ' + job.job_url,
  '',
  'CANDIDATE PROFILE:',
  'Name: ' + job.profile.name,
  'Background: ' + job.profile.summary,
  'Skills: ' + job.profile.skills.join(', '),
  'Experience: ' + job.profile.experience.map(e => e.title + ' @ ' + e.company + ' (' + e.period + ')').join(' | '),
  'Education: ' + job.profile.education.map(e => e.degree + ' — ' + e.school).join(' | '),
  'Certifications: ' + job.profile.certifications.join(', '),
  '',
  'Return ONLY valid JSON.'
].join('\n');

return [{
  json: {
    job_id: job.job_id, title: job.title, company: job.company,
    location: job.location, job_url: job.job_url,
    date_found: job.date_found, relevance_score: job.relevance_score,
    matched_skills: job.matched_skills,
    openai_body: JSON.stringify({
      model: 'gpt-4o-mini',
      max_tokens: 1200,
      response_format: { type: 'json_object' },
      messages: [
        { role: 'system', content: systemPrompt },
        { role: 'user',   content: userPrompt }
      ]
    })
  }
}];

const aiResp  = $input.item.json;
const jobMeta = $('Build AI Prompt').item.json;

let content = {};
try {
  const raw     = aiResp.choices?.[0]?.message?.content || '{}';
  const cleaned = raw.replace(/```json\n?|```/g, '').trim();
  content       = JSON.parse(cleaned);
} catch (e) {
  content = { tailored_summary: '', key_skills: [], cover_note: '',
    match_assessment: 'Parse error: ' + (aiResp.choices?.[0]?.message?.content || '').slice(0, 200) };
}

return [{
  json: {
    job_id:           jobMeta.job_id,
    title:            jobMeta.title,
    company:          jobMeta.company,
    location:         jobMeta.location,
    job_url:          jobMeta.job_url,
    relevance_score:  jobMeta.relevance_score,
    matched_skills:   jobMeta.matched_skills,
    date_generated:   new Date().toISOString().split('T')[0],
    tailored_summary: content.tailored_summary || '',
    key_skills:       Array.isArray(content.key_skills) ? content.key_skills.join(', ') : (content.key_skills || ''),
    cover_note:       content.cover_note || '',
    match_assessment: content.match_assessment || ''
  }
}];
